'use strict';
(function initHljsShim(global){
  function escapeHtml(str){
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  const hljs = {
    getLanguage(){
      return true;
    },
    highlight(code){
      return { value: escapeHtml(code) };
    },
    highlightAuto(code){
      return { value: escapeHtml(code) };
    },
  };

  global.hljs = hljs;
})(typeof globalThis !== 'undefined' ? globalThis : window);
